parameterdescription.para:
使用するハッシュ型。 Example Srpsrp;
if(wc_SrpInit(&srp,SRP_TYPE_SHA,SRP_CLIENT_SIDE)!=0)
{
//Initializationerror
}
else
{
wc_SrpTerm(&srp);
}

simplesect.para:
none いいえ返します。 Example Srpsrp;
wc_SrpInit(&srp,SRP_TYPE_SHA,SRP_CLIENT_SIDE);
//Usesrp
wc_SrpTerm(&srp)

parameterdescription.para:
ユーザー名を含むバッファ。 Example Srpsrp;
byteusername[]="user";
word32usernameSize=4;

wc_SrpInit(&srp,SRP_TYPE_SHA,SRP_CLIENT_SIDE);
if(wc_SrpSetUsername(&srp,username,usernameSize)!=0)
{
//Erroroccurredsettingusername.
}
wc_SrpTerm(&srp);

小さいランダムな塩。各ユーザー名に特有のものです。 Example Srpsrp;
byteusername[]="user";
word32usernameSize=4;

byteN[]={};//ContentsofbytearrayN
byteg[]={};//Contentsofbytearrayg
bytesalt[]={};//Contentsofbytearraysalt

wc_SrpInit(&srp,SRP_TYPE_SHA,SRP_CLIENT_SIDE);
wc_SrpSetUsername(&srp,username,usernameSize);

if(wc_SrpSetParams(&srp,N,sizeof(N),g,sizeof(g),salt,
sizeof(salt))!=0)
{
//Errorsettingparams
}
wc_SrpTerm(&srp);

パスワードを含むバッファ。 Example Srpsrp;
byteusername[]="user";
word32usernameSize=4;
bytepassword[]="password";
word32passwordSize=8;

byteN[]={};//ContentsofbytearrayN
byteg[]={};//Contentsofbytearrayg
bytesalt[]={};//Contentsofbytearraysalt

wc_SrpInit(&srp,SRP_TYPE_SHA,SRP_CLIENT_SIDE);
wc_SrpSetUsername(&srp,username,usernameSize);
wc_SrpSetParams(&srp,N,sizeof(N),g,sizeof(g),salt,sizeof(salt));

if(wc_SrpSetPassword(&srp,password,passwordSize)!=0)
{
//Errorsettingpassword
}

wc_SrpTerm(&srp);

検証者を含む構造体。 Example Srpsrp;
byteusername[]="user";
word32usernameSize=4;

byteN[]={};//ContentsofbytearrayN
byteg[]={};//Contentsofbytearrayg
bytesalt[]={};//Contentsofbytearraysalt
wc_SrpInit(&srp,SRP_TYPE_SHA,SRP_SERVER_SIDE);
wc_SrpSetUsername(&srp,username,usernameSize);
wc_SrpSetParams(&srp,N,sizeof(N),g,sizeof(g),salt,sizeof(salt))
byteverifier[]={};//Contentsofsomeverifier

if(wc_SrpSetVerifier(&srp,verifier,sizeof(verifier))!=0)
{
//Errorsettingverifier
}

wc_SrpTerm(&srp);

検証者を書き込むためのバッファー。 Example Srpsrp;
byteusername[]="user";
word32usernameSize=4;
bytepassword[]="password";
word32passwordSize=8;

byteN[]={};//ContentsofbytearrayN
byteg[]={};//Contentsofbytearrayg
bytesalt[]={};//Contentsofbytearraysalt
bytev[64];
word32vSz=0;
vSz=sizeof(v);

wc_SrpInit(&srp,SRP_TYPE_SHA,SRP_CLIENT_SIDE);
wc_SrpSetUsername(&srp,username,usernameSize);
wc_SrpSetParams(&srp,N,sizeof(N),g,sizeof(g),salt,sizeof(salt))
wc_SrpSetPassword(&srp,password,passwordSize)

if(wc_SrpGetVerifier(&srp,v,&vSz)!=0)
{
//Errorgettingverifier
}
wc_SrpTerm(&srp);

一時的な値。 Example Srpsrp;
byteusername[]="user";
word32usernameSize=4;

byteN[]={};//ContentsofbytearrayN
byteg[]={};//Contentsofbytearrayg
bytesalt[]={};//Contentsofbytearraysalt
byteverifier={};//Contentsofsomeverifier
wc_SrpInit(&srp,SRP_TYPE_SHA,SRP_SERVER_SIDE);
wc_SrpSetUsername(&srp,username,usernameSize);
wc_SrpSetParams(&srp,N,sizeof(N),g,sizeof(g),salt,sizeof(salt))
wc_SrpSetVerifier(&srp,verifier,sizeof(verifier))

byteb[]={};//Someephemeralvalue
if(wc_SrpSetPrivate(&srp,b,sizeof(b))!=0)
{
//Errorsettingprivateephemeral
}

wc_SrpTerm(&srp);

パブリックエフェラル値を書き込むためのバッファ。 Example Srpsrp;
byteusername[]="user";
word32usernameSize=4;
bytepassword[]="password";
word32passwordSize=8;

byteN[]={};//ContentsofbytearrayN
byteg[]={};//Contentsofbytearrayg
bytesalt[]={};//Contentsofbytearraysalt
wc_SrpInit(&srp,SRP_TYPE_SHA,SRP_CLIENT_SIDE);
wc_SrpSetUsername(&srp,username,usernameSize);
wc_SrpSetParams(&srp,N,sizeof(N),g,sizeof(g),salt,sizeof(salt));
wc_SrpSetPassword(&srp,password,passwordSize)

bytepublic[64];
word32publicSz=0;

if(wc_SrpGetPublic(&srp,public,&publicSz)!=0)
{
//Errorgettingpublicephemeral
}

wc_SrpTerm(&srp);

サーバーの一般の一時的な値。 Example Srpserver;

byteusername[]="user";
word32usernameSize=4;
bytepassword[]="password";
word32passwordSize=8;
byteN[]={};//ContentsofbytearrayN
byteg[]={};//Contentsofbytearrayg
bytesalt[]={};//Contentsofbytearraysalt
byteverifier[]={};//Contentsofsomeverifier
byteserverPubKey[]={};//Contentsofserverpubkey
word32serverPubKeySize=sizeof(serverPubKey);
byteclientPubKey[64];
word32clientPubKeySize=64;

wc_SrpInit(&server,SRP_TYPE_SHA,SRP_SERVER_SIDE);
wc_SrpSetUsername(&server,username,usernameSize);
wc_SrpSetParams(&server,N,sizeof(N),g,sizeof(g),salt,sizeof(salt));
wc_SrpSetVerifier(&server,verifier,sizeof(verifier));
wc_SrpGetPublic(&server,serverPubKey,&serverPubKeySize);

wc_SrpComputeKey(&server,clientPubKey,clientPubKeySz,
serverPubKey,serverPubKeySize)
wc_SrpTerm(&server);

ピアプルーフ。 Example Srpcli;
byteclientProof[SRP_MAX_DIGEST_SIZE];
word32clientProofSz=SRP_MAX_DIGEST_SIZE;

//InitializeSrpfollowingstepsfrompreviousexamples

if(wc_SrpGetProof(&cli,clientProof,&clientProofSz)!=0)
{
//Errorgettingproof
}

ピアプルーフ。 Example Srpcli;
Srpsrv;
byteclientProof[SRP_MAX_DIGEST_SIZE];
word32clientProofSz=SRP_MAX_DIGEST_SIZE;

//InitializeSrpfollowingstepsfrompreviousexamples
//Firstgettheproof
wc_SrpGetProof(&cli,clientProof,&clientProofSz)

if(wc_SrpVerifyPeersProof(&srv,clientProof,clientProofSz)!=0)
{
//Errorverifyingproof
}
